<?php get_header(); while(have_posts()):the_post(); ?><article class="article wrap"><div class="eyebrow"><?php echo ma_theme_location_label(); ?> · <?php $c=get_the_category();echo esc_html($c[0]->name??'Aktuell'); ?></div><h1><?php the_title(); ?></h1><?php if(has_excerpt()): ?><p class="article-dek"><?php echo esc_html(get_the_excerpt()); ?></p><?php endif; ?><div class="meta-line"><span>Von <?php the_author(); ?></span><span><?php echo esc_html(get_the_date('d.m.Y · H:i')); ?> Uhr</span><span><?php echo ma_theme_reading_time(); ?> Min. Lesezeit</span><a href="#comments"><?php echo (int)get_comments_number(); ?> Kommentare</a></div><?php if(has_post_thumbnail()): ?><figure class="article-hero"><?php the_post_thumbnail('full'); if($cr=get_post_meta(get_the_ID(),'ma_image_credit',true)): ?><figcaption><?php echo esc_html($cr); ?></figcaption><?php endif; ?></figure><?php endif; ?><?php if($facts=get_post_meta(get_the_ID(),'ma_facts',true)): ?><div class="facts"><strong>Das Wichtigste in Kürze</strong><p><?php echo esc_html($facts); ?></p></div><?php endif; ?><div class="article-body"><?php the_content(); ?></div><div class="source-box"><strong>Quelle & Transparenz</strong><br><?php $pub=get_post_meta(get_the_ID(),'ma_source_publisher',true);$url=get_post_meta(get_the_ID(),'ma_source_url',true);echo esc_html($pub?:'Redaktion Merzenich Aktuell'); if($url) echo ' · <a href="'.esc_url($url).'" target="_blank" rel="noopener">Originalquelle</a>'; ?><?php if(get_post_meta(get_the_ID(),'ma_ai_used',true)==='1'): ?><br>KI wurde redaktionell eingesetzt. Menschliche Prüfung: <?php echo get_post_meta(get_the_ID(),'ma_human_reviewed',true)==='1'?'ja':'noch nicht dokumentiert'; ?>.<?php endif; ?></div><?php the_tags('<p>Tags: ',', ','</p>'); ?><?php $cats=wp_get_post_categories(get_the_ID());$rel=new WP_Query(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>3,'post__not_in'=>[get_the_ID()],'category__in'=>$cats]);if($rel->have_posts()): ?><h2 class="section-title">Mehr aus Merzenich</h2><div class="news-list"><?php while($rel->have_posts()):$rel->the_post();get_template_part('template-parts/card');endwhile;wp_reset_postdata(); ?></div><?php endif; ?><?php if(comments_open()||get_comments_number()) comments_template(); ?></article><?php endwhile; get_footer(); ?>
